"use client"

import type { ReactNode } from "react"
import { Icon } from "@/components/ui/icon-provider"
import { cn } from "@/lib/utils"
import { Checkbox } from "@/components/ui/checkbox"
import { IconButton } from "@/components/ui/icon-button"

type ItemCardTint = "indigo" | "blue" | "purple" | "pink" | "red" | "orange" | "yellow" | "green" | "alternative"

const ITEM_CARD_TINT: Record<ItemCardTint, string> = {
  indigo: "bg-tint-indigo text-tint-text-indigo",
  blue: "bg-tint-blue text-tint-text-blue",
  purple: "bg-tint-purple text-tint-text-purple",
  pink: "bg-tint-pink text-tint-text-pink",
  red: "bg-tint-red text-tint-text-red",
  orange: "bg-tint-orange text-tint-text-orange",
  yellow: "bg-tint-yellow text-tint-text-yellow",
  green: "bg-tint-green text-tint-text-green",
  alternative: "bg-tint-alternative text-tint-text-alternative",
}

function ItemCard({
  icon,
  title,
  description,
  meta,
  action,
  className,
}: {
  icon?: ReactNode
  title: ReactNode
  description?: ReactNode
  meta?: ReactNode
  action?: ReactNode
  className?: string
}) {
  return (
    <div
      className={cn(
        "flex items-center gap-3 rounded-md border border-border bg-card p-3",
        className
      )}
    >
      {icon && (
        <div className="flex size-10 shrink-0 items-center justify-center rounded-md bg-tint-indigo text-tint-text-indigo [&_svg]:size-5">
          {icon}
        </div>
      )}
      <div className="flex min-w-0 flex-1 flex-col gap-0.5">
        <p className="truncate text-sm font-semibold text-foreground">{title}</p>
        {description && (
          <p className="truncate text-[13px] text-text-secondary">{description}</p>
        )}
      </div>
      {meta && <div className="shrink-0 text-xs text-text-tertiary">{meta}</div>}
      {action && <div className="shrink-0">{action}</div>}
    </div>
  )
}

function ItemCardGroup({
  children,
  className,
}: {
  children: ReactNode
  className?: string
}) {
  return (
    <div className={cn("flex flex-col gap-2 rounded-lg border border-border bg-card p-2", className)}>
      {children}
    </div>
  )
}


/* ------------------------------------------------------------------ */
/* ItemCardCover — a clickable tile with a tinted cover, name and meta  */
/* Figma: Project Card (693:146)                                       */
/* ------------------------------------------------------------------ */

type ItemCardCoverProps = {
  name: ReactNode
  /** One short line under the name. */
  meta?: ReactNode
  /** Tint of the cover band. */
  color?: ItemCardTint
  /** Icon, logo or image in the middle of the cover. */
  cover?: ReactNode
  onClick?: () => void
  className?: string
}

function ItemCardCover({ name, meta, color = "indigo", cover, onClick, className }: ItemCardCoverProps) {
  return (
    <button
      type="button"
      data-slot="item-card-cover"
      onClick={onClick}
      className={cn("flex flex-col overflow-hidden rounded-xl border border-border bg-card text-start transition-colors duration-fast ease-entrance hover:bg-bg-page active:bg-bg-subtle outline-none focus-ring", className)}
    >
      <span className={cn("flex h-24 w-full items-center justify-center", ITEM_CARD_TINT[color])}>{cover}</span>
      <span className="flex flex-col p-3">
        <span className="truncate text-xs font-semibold text-foreground">{name}</span>
        {meta && <span className="truncate text-[11px] text-text-tertiary">{meta}</span>}
      </span>
    </button>
  )
}

/* ------------------------------------------------------------------ */
/* ItemCardFile — a file tile: preview, name, details, selection, menu  */
/* Figma: File Card (702:57)                                           */
/* ------------------------------------------------------------------ */

type ItemCardFileProps = {
  name: ReactNode
  meta?: ReactNode
  icon?: ReactNode
  color?: ItemCardTint
  /** Image preview instead of the icon tile. */
  thumbnail?: string
  selected?: boolean
  onSelectedChange?: (selected: boolean) => void
  /** Type=trash — deletion line shown in red, no menu/checkbox. */
  deletedAt?: ReactNode
  onMenu?: () => void
  onOpen?: () => void
  className?: string
}

function ItemCardFile({ name, meta, icon, color = "red", thumbnail, selected, onSelectedChange, deletedAt, onMenu, onOpen, className }: ItemCardFileProps) {
  return (
    <div
      data-slot="item-card-file"
      data-selected={selected || undefined}
      className={cn(
        "group/file flex flex-col overflow-hidden rounded-xl border bg-card transition-colors duration-fast ease-entrance",
        selected ? "border-primary" : "border-border",
        className
      )}
    >
      {/* onOpen: a real button covers the preview; the checkbox sits above it
          as a sibling, so no interactive element is nested in another. */}
      <div
        className={cn(
          "relative flex h-[120px] items-center justify-center [&>svg]:size-9",
          ITEM_CARD_TINT[color],
          onOpen && "has-[[data-open]:focus-visible]:focus-ring-on"
        )}
      >
        {thumbnail ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img src={thumbnail} alt="" className="size-full object-cover" />
        ) : (
          (icon ?? <Icon name="document" strokeWidth={1.5} />)
        )}
        {onOpen && (
          <button type="button" data-open onClick={onOpen} className="absolute inset-0 cursor-pointer outline-none">
            <span className="sr-only">Open {name}</span>
          </button>
        )}
        {onSelectedChange && (
          <Checkbox
            aria-label="Select file"
            checked={!!selected}
            onCheckedChange={(v) => onSelectedChange(!!v)}
            className={cn("absolute top-2 start-2 size-6 bg-card transition-opacity duration-fast ease-entrance", !selected && "opacity-0 group-hover/file:opacity-100 focus-visible:opacity-100")}
          />
        )}
      </div>
      <div className="flex items-start gap-2 p-3">
        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
          <p className="truncate text-xs font-medium text-foreground">{name}</p>
          {meta && <p className="truncate text-[11px] text-text-tertiary">{meta}</p>}
          {deletedAt && <p className="text-[11px] text-text-error">{deletedAt}</p>}
        </div>
        {onMenu && !deletedAt && (
          <IconButton variant="ghost" size="sm" aria-label="File menu" onClick={onMenu} className="-mt-1 -me-1">
            <Icon name="moreVertical" className="size-4" strokeWidth={1.5} />
          </IconButton>
        )}
      </div>
    </div>
  )
}

export { ItemCard, ItemCardGroup, ItemCardCover, ItemCardFile, ITEM_CARD_TINT }
export type { ItemCardTint, ItemCardCoverProps, ItemCardFileProps }

import * as React from "react"
import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"
import { Icon } from "@/components/ui/icon-provider"
import { cn } from "@/lib/utils"

// Same states as Button (see button.tsx and the Figma Button / Icon set): the filled variants use fixed
// hover and pressed fills (brand-700/800, red-800/900, dark-400/500, bg-page/bg-subtle on neutral surfaces)
// instead of brightness-95, and focus is the shared 2 px focus-ring (owner rule 31 Oct 2026). The gradient top
// stop is 85 % primary + 15 % brand-500 (4.73:1 with a white icon); hover and pressed step the gradient to
// brand-600/700 and brand-700/800. The light variant's icon is light-1000 (5.93:1 on light-600); it has no
// Figma counterpart, hover and pressed step to the lighter light-500 and light-400 so the icon keeps >= 3:1.
const iconButtonVariants = cva(
  "group/icon-button inline-flex shrink-0 items-center justify-center border border-transparent transition duration-fast ease-entrance outline-none select-none shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05)] active:scale-[0.97] motion-reduce:active:scale-100 disabled:pointer-events-none disabled:opacity-40 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        plain: "bg-card border-border-control text-foreground hover:bg-bg-page data-expanded:bg-bg-subtle data-expanded:hover:bg-bg-subtle active:bg-bg-subtle focus-ring",
        primary:
          "border-primary bg-primary text-primary-foreground hover:border-(color:--brand-700) hover:bg-(--brand-700) active:border-(color:--brand-800) active:bg-(--brand-800) focus-ring",
        brand:
          "border-brand-primary bg-brand-primary text-brand-primary-foreground hover:border-(color:--brand-700) hover:bg-(--brand-700) active:border-(color:--brand-800) active:bg-(--brand-800) focus-ring",
        gradient:
          "border-primary bg-gradient-to-b from-[color-mix(in_srgb,var(--primary)_85%,var(--brand-500))] to-primary text-primary-foreground shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05),inset_0px_1px_2px_0px_rgba(255,255,255,0.35)] hover:from-(--brand-600) hover:to-(--brand-700) active:from-(--brand-700) active:to-(--brand-800) focus-ring",
        dark: "bg-inverse text-text-inverse hover:bg-(--dark-400) hover:text-neutral-white active:bg-(--dark-500) active:text-neutral-white focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-0 focus-visible:outline-(color:--dark-300)",
        light: "bg-(--light-600) text-(--light-1000) hover:bg-(--light-500) data-expanded:bg-bg-subtle data-expanded:hover:bg-bg-subtle active:bg-(--light-400) focus-ring",
        outline: "bg-card border-primary text-foreground hover:border-tint-text-indigo hover:bg-tint-indigo hover:text-tint-text-indigo data-expanded:bg-bg-subtle data-expanded:hover:bg-bg-subtle active:bg-bg-subtle focus-ring",
        // Figma Type=ghost / destructive (added Sep 2026)
        ghost: "bg-transparent text-foreground shadow-none hover:bg-bg-page data-expanded:bg-bg-subtle data-expanded:hover:bg-bg-subtle active:bg-bg-subtle focus-ring",
        destructive:
          "border-destructive bg-destructive text-destructive-foreground hover:border-(color:--red-800) hover:bg-(color:--red-800) active:border-(color:--red-900) active:bg-(color:--red-900) focus-ring-error",
      },
      shape: {
        rounded: "rounded-md",
        circle: "rounded-full",
      },
      size: {
        sm: "size-8 [&_svg]:size-4",
        md: "size-9 [&_svg]:size-[18px]",
        lg: "size-10 [&_svg]:size-5",
        xl: "size-11 [&_svg]:size-[22px]",
        "2xl": "size-12 [&_svg]:size-6",
      },
    },
    defaultVariants: {
      variant: "primary",
      shape: "rounded",
      size: "md",
    },
  }
)

type IconButtonPhase = "idle" | "pending" | "success" | "error"

function IconButton({
  className,
  variant,
  shape,
  size,
  children,
  onClick,
  pending,
  phase,
  expanded,
  ...props
}: ButtonPrimitive.Props &
  VariantProps<typeof iconButtonVariants> & {
    /**
     * Shows a spinner in place of the icon, in the same square, and ignores presses.
     * The button stays focusable and keeps its colour (it is not disabled).
     */
    pending?: boolean
    /**
     * Async feedback in the same square: pending shows a spinner, success a check, error a retry icon.
     * The size never changes. The accessible name is yours: change the aria-label with the phase
     * (for example Copy link, Copying, Copied, Retry copying).
     */
    phase?: IconButtonPhase
    /**
     * Marks a trigger whose menu or panel is open: sets aria-expanded and the pressed surface
     * (bg-bg-subtle) on the quiet variants. Leave it undefined when the button does not control a popup.
     */
    expanded?: boolean
  }) {
  const status: IconButtonPhase = phase ?? (pending ? "pending" : "idle")
  const isIdle = status === "idle"

  const resolvedVariant = variant ?? "primary"
  const effectiveVariant =
    status === "error" && ["primary", "brand", "gradient"].includes(resolvedVariant)
      ? "destructive"
      : variant

  const quiet = ["plain", "ghost", "outline"].includes(resolvedVariant)

  let statusIcon: React.ReactNode = null
  if (status === "pending") {
    statusIcon = (
      <Icon name="spinner" aria-hidden className="animate-spin motion-reduce:animate-none" />
    )
  } else if (status === "success") {
    statusIcon = (
      <Icon name="check" aria-hidden strokeWidth={2} className={quiet ? "text-text-success" : undefined} />
    )
  } else if (status === "error") {
    statusIcon = (
      <Icon name="retry" aria-hidden strokeWidth={2} className={quiet ? "text-text-error" : undefined} />
    )
  }

  const handleClick: NonNullable<ButtonPrimitive.Props["onClick"]> = (event) => {
    if (status === "pending") {
      event.preventDefault()
      return
    }
    onClick?.(event)
  }

  return (
    <ButtonPrimitive
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant: isIdle ? variant : effectiveVariant, shape, size, className }))}
      aria-expanded={expanded}
      data-expanded={expanded ? "" : undefined}
      data-phase={isIdle ? undefined : status}
      aria-busy={isIdle ? undefined : status === "pending" ? true : undefined}
      data-pending={isIdle ? undefined : status === "pending" ? "" : undefined}
      onClick={isIdle ? onClick : handleClick}
      {...props}
    >
      {isIdle ? children : statusIcon}
    </ButtonPrimitive>
  )
}

export { IconButton, iconButtonVariants }
export type { IconButtonPhase }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm", "micro"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})

"use client"

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"
import { cn } from "@/lib/utils"
import { Icon } from "@/components/ui/icon-provider"
import * as React from "react"

/**
 * Base UI renders a hidden native <input> next to the visible control and gives it no name.
 * It is aria-hidden, but page checkers still list it as an unlabelled form control, so the
 * control's aria-label / aria-labelledby is mirrored onto it.
 */
function useNamedHiddenInput(inputRef: React.Ref<HTMLInputElement> | undefined, label?: string, labelledBy?: string) {
  return React.useCallback(
    (node: HTMLInputElement | null) => {
      if (node) {
        if (label) node.setAttribute("aria-label", label)
        else node.removeAttribute("aria-label")
        if (labelledBy) node.setAttribute("aria-labelledby", labelledBy)
        else node.removeAttribute("aria-labelledby")
      }
      if (typeof inputRef === "function") inputRef(node)
      else if (inputRef) (inputRef as React.RefObject<HTMLInputElement | null>).current = node
    },
    [inputRef, label, labelledBy]
  )
}

// Figma Appearance=Neutral: the filled box is the inverse surface (black in light, white in dark)
// with an inverse-coloured check instead of the brand fill. Hover and disabled stay as they are; an invalid box keeps its red rim.
const NEUTRAL_CHECKED =
  "data-checked:border-inverse data-checked:bg-inverse data-checked:text-text-inverse dark:data-checked:bg-inverse data-indeterminate:border-inverse data-indeterminate:bg-inverse data-indeterminate:text-text-inverse group-has-[:focus-visible]/field-label:data-checked:border-inverse"

// Figma Appearance=Brand: the filled box darkens on hover (brand-700) and pressed (brand-800), the same
// fixed tokens as the primary button, so the white mark keeps its contrast in both themes (7.0:1, 10.0:1).
// The border follows the fill unless the box is invalid (the red rim stays).
const BRAND_STATES =
  "hover:data-checked:bg-(--brand-700) hover:data-indeterminate:bg-(--brand-700) active:data-checked:bg-(--brand-800) active:data-indeterminate:bg-(--brand-800) hover:data-checked:not-aria-invalid:border-(color:--brand-700) hover:data-indeterminate:not-aria-invalid:border-(color:--brand-700) active:data-checked:not-aria-invalid:border-(color:--brand-800) active:data-indeterminate:not-aria-invalid:border-(color:--brand-800)"

type CheckboxControlProps = CheckboxPrimitive.Root.Props & {
  /** `brand` fills the checked box with the brand colour; `neutral` fills it with the inverse (black/white) surface. */
  appearance?: "brand" | "neutral"
}

type CheckboxFieldProps = {
  /** Visible label to the right of the box. Joined to the box with `htmlFor`; a click on it toggles the box. */
  label?: React.ReactNode
  /** A second line under the label in the tertiary colour. */
  description?: React.ReactNode
  /** Error message under the row. Sets `aria-invalid` and `aria-describedby` on the box and turns its rim red. */
  error?: React.ReactNode
  /** Class names for the row (or, with `error`, for the wrapper around the row and the message). */
  wrapperClassName?: string
}

type CheckboxProps = CheckboxControlProps & CheckboxFieldProps

/** The props that turn the bare box into a field row. Presence of the prop counts, not its value, so a
 *  conditional `error={cond ? "…" : undefined}` never swaps the DOM (and drops the focus) when it flips. */
const FIELD_PROPS = ["label", "description", "error", "wrapperClassName"] as const

/**
 * Checkbox. Without any of the field props (`label`, `description`, `error`,
 * `wrapperClassName`) it renders the bare box. With one of them it renders the
 * row: the box and its label (and description) in one `<label>`, so the whole
 * row is the click target; `error` adds the message under the row.
 */
function Checkbox(props: CheckboxProps) {
  const autoId = React.useId()
  if (!FIELD_PROPS.some((key) => key in props)) return <CheckboxControl {...props} />

  const { label, description, error, wrapperClassName, id: idProp, className, ...rest } = props
  const id = idProp ?? autoId
  // The message sits outside the label so it is not read as part of the box's name.
  const withMessage = "error" in props
  const row = (
    <label
      htmlFor={id}
      data-slot={withMessage ? undefined : "checkbox-field"}
      className={cn("group/checkbox-field flex cursor-pointer items-start gap-2 has-[[data-disabled]]:cursor-not-allowed", !withMessage && wrapperClassName)}
    >
      <CheckboxControl
        id={id}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? `${id}-error` : undefined}
        className={cn("mt-0.5", className)}
        {...rest}
      />
      <span className="flex flex-col gap-0.5">
        {label && (
          <span className="text-sm text-text-secondary group-has-[[data-disabled]]/checkbox-field:opacity-40 [&_a]:font-medium [&_a]:text-text-link [&_a]:hover:underline">{label}</span>
        )}
        {description && <span className="text-xs text-text-tertiary group-has-[[data-disabled]]/checkbox-field:opacity-40">{description}</span>}
      </span>
    </label>
  )
  if (!withMessage) return row
  return (
    <div data-slot="checkbox-field" className={cn("flex flex-col gap-1", wrapperClassName)}>
      {row}
      {error && (
        <p id={`${id}-error`} className="ps-6 text-xs text-text-error">
          {error}
        </p>
      )}
    </div>
  )
}

function CheckboxControl({
  className,
  inputRef,
  appearance = "brand",
  ...props
}: CheckboxControlProps) {
  const namedInputRef = useNamedHiddenInput(inputRef, props["aria-label"], props["aria-labelledby"])
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      data-appearance={appearance}
      inputRef={namedInputRef}
      className={cn(
        "peer relative flex size-4 shrink-0 items-center justify-center rounded-[4px] border border-border-control bg-card transition-colors duration-fast ease-entrance outline-none hover:not-data-checked:not-data-indeterminate:not-aria-invalid:border-primary active:not-data-checked:not-data-indeterminate:not-aria-invalid:border-primary hover:not-data-checked:not-data-indeterminate:bg-bg-page active:not-data-checked:not-data-indeterminate:bg-bg-subtle after:absolute after:-inset-x-3 after:-inset-y-2 focus-ring data-disabled:cursor-not-allowed data-disabled:opacity-40 aria-invalid:border-error aria-invalid:focus-ring-error data-checked:border-primary data-checked:bg-primary data-checked:text-primary-foreground data-indeterminate:border-primary data-indeterminate:bg-primary data-indeterminate:text-primary-foreground aria-invalid:data-checked:border-error aria-invalid:data-indeterminate:border-error",
        appearance === "brand" && BRAND_STATES,
        appearance === "neutral" && NEUTRAL_CHECKED,
        className
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        keepMounted
        data-slot="checkbox-indicator"
        className={cn(
          "grid place-content-center text-current opacity-0 transition-opacity ease-entrance duration-fast data-checked:opacity-100 data-indeterminate:opacity-100 [&>svg]:size-3.5 [&>svg:last-child]:hidden data-indeterminate:[&>svg:first-child]:hidden data-indeterminate:[&>svg:last-child]:block",
          // The box fills instantly (see Root's data-checked:bg-primary above);
          // the check stroke draws in after via stroke-dashoffset. 23 is
          // lucide's CheckIcon path length (getTotalLength()), rounded up by 1
          // so the draw never over/under-shoots. Uncheck reverses fast with no
          // draw — transitioning offset (not toggling display) is what lets a
          // mid-draw uncheck reverse cleanly instead of jumping. The offset is
          // negative because lucide's path starts at the top-right end: the
          // tick draws from its short stroke up to the long one, like by hand.
          "[&_svg_path]:[stroke-dasharray:23] [&_svg_path]:[stroke-dashoffset:-23] [&_svg_path]:transition-[stroke-dashoffset] [&_svg_path]:duration-fast [&_svg_path]:ease-entrance data-checked:[&_svg_path]:[stroke-dashoffset:0] data-indeterminate:[&_svg_path]:[stroke-dashoffset:0] data-checked:[&_svg_path]:duration-slow"
        )}
      >
        {/* the roles checkboxCheck / checkboxIndeterminate (ui/icon-provider.tsx) draw Lucide heavier so the mark reads at 16 px: 3 on lucide's 24 grid for the check (about 1.75 px at 14 px), 4 for the minus, a short bar that looks thinner than the check at the same weight */}
        <Icon name="checkboxCheck" />
        <Icon name="checkboxIndeterminate" />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  )
}

export { Checkbox }
export type { CheckboxProps }
